import { elements, user } from "./modele.js";document.addEventListener("DOMContentLoaded", e => {
  e.preventDefault(), console.log("chargement du document completée");for (let data in user) "cover" != data ? elements.elParent.innerHTML += `<li><strong>${data}</strong> : ${user[data]} </li>` : elements.elImg.src = `${user[data]}`;
});